COMMENT ON COLUMN studies.source IS 'Citation or description of the original data source.';
COMMENT ON COLUMN studies.source_url IS 'URL to the original source.';
COMMENT ON COLUMN studies.publication_year IS 'Year the study was published. Used for temporal stratification and pre-registration dating.';
COMMENT ON COLUMN studies.domain IS 'Research domain: medicine | epidemiology | social-science | education | legal | sports | economics | synthetic. Enables cross-domain SignalPurity stratification.';
COMMENT ON COLUMN studies.is_synthetic IS 'TRUE for constructed/counterfactual studies; FALSE for real published studies. Filters the corpus for empirical claims.';
COMMENT ON COLUMN studies.tradition_id IS 'FK → ResearchTraditions.TraditionId. The scholarly tradition whose framing best characterizes this study''s paradox type. Synthetic studies inherit the tradition of their conceptual origin.';
COMMENT ON COLUMN studies.primary_researcher_id IS 'FK → Researchers.ResearcherId. The researcher most associated with first surfacing or canonically citing this study in the Simpson''s Paradox literature.';
COMMENT ON COLUMN studies.is_control_study IS 'TRUE if this study is a control (no Simpson''s paradox expected/found); FALSE for the main Simpson''s Paradox corpus.';
COMMENT ON COLUMN studies.control_domain IS 'Domain slug for control studies (e.g. medicine-rct, education-higher). NULL for non-control studies.';
COMMENT ON COLUMN studies.valid_time_start IS 'First year of the real-world cohort period this study''s data covers (valid-time, not publication year). Defaults to PublicationYear when the true cohort window is not independently known.';
COMMENT ON COLUMN studies.valid_time_end IS 'Last year of the real-world cohort period this study''s data covers (valid-time, not publication year). Defaults to PublicationYear when the true cohort window is not independently known.';

-- ----------------------------------------------------------------------------
-- Treatments: Table: Treatments — the interventions being compared within a study. Each treatment belongs to one study.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS treatments (
  treatment_id                        TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-A, kidney-1986-B).
);
ALTER TABLE treatments ADD COLUMN IF NOT EXISTS study TEXT;                                         -- FK to the parent Study.
ALTER TABLE treatments ADD COLUMN IF NOT EXISTS treatment_label TEXT;                               -- Short label used in CaseCells and comparisons (e.g. A, B).
ALTER TABLE treatments ADD COLUMN IF NOT EXISTS description TEXT;                                   -- Plain-language description of what this treatment is.
COMMENT ON TABLE treatments IS 'Table: Treatments — the interventions being compared within a study. Each treatment belongs to one study.';
COMMENT ON COLUMN treatments.treatment_id IS 'Unique slug (e.g. kidney-1986-A, kidney-1986-B).';
COMMENT ON COLUMN treatments.study IS 'FK to the parent Study.';
COMMENT ON COLUMN treatments.treatment_label IS 'Short label used in CaseCells and comparisons (e.g. A, B).';
COMMENT ON COLUMN treatments.description IS 'Plain-language description of what this treatment is.';

-- ----------------------------------------------------------------------------
-- Strata: Table: Strata — the subdivisions of patients within a study by the value of the confounding variable (e.g. stone size). Each stratum belongs to one study.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS strata (
  stratum_id                          TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-small, kidney-1986-large).
);
ALTER TABLE strata ADD COLUMN IF NOT EXISTS study TEXT;                                             -- FK to the parent Study.
ALTER TABLE strata ADD COLUMN IF NOT EXISTS stratum_label TEXT;                                     -- Short label used in CaseCells (e.g. small, large, dept-A).
ALTER TABLE strata ADD COLUMN IF NOT EXISTS description TEXT;                                       -- Plain-language description of what defines this stratum.
COMMENT ON TABLE strata IS 'Table: Strata — the subdivisions of patients within a study by the value of the confounding variable (e.g. stone size). Each stratum belongs to one study.';
COMMENT ON COLUMN strata.stratum_id IS 'Unique slug (e.g. kidney-1986-small, kidney-1986-large).';
COMMENT ON COLUMN strata.study IS 'FK to the parent Study.';
COMMENT ON COLUMN strata.stratum_label IS 'Short label used in CaseCells (e.g. small, large, dept-A).';
COMMENT ON COLUMN strata.description IS 'Plain-language description of what defines this stratum.';

-- ----------------------------------------------------------------------------
-- CaseCells: Table: CaseCells — the raw leaves of the DAG. One row per (study, stratum, treatment) combination recording the aggregate count of successes and total cases. Every derived fact in the model traces back to these numbers. Nothing above this row is a raw input.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS case_cells (
  case_cell_id                        TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-small-A).
);
ALTER TABLE case_cells ADD COLUMN IF NOT EXISTS study TEXT;                                         -- FK to the parent Study.
ALTER TABLE case_cells ADD COLUMN IF NOT EXISTS stratum_label TEXT;                                 -- The stratum this cell belongs to (matches Strata.StratumLabel).
ALTER TABLE case_cells ADD COLUMN IF NOT EXISTS treatment_label TEXT;                               -- The treatment applied in this cell (matches Treatments.TreatmentLabel).
ALTER TABLE case_cells ADD COLUMN IF NOT EXISTS successes INTEGER;                                  -- Number of patients in this cell who had a successful outcome. RAW INPUT — never derived.
ALTER TABLE case_cells ADD COLUMN IF NOT EXISTS cases INTEGER;                                      -- Total number of patients in this cell. RAW INPUT — never derived.
COMMENT ON TABLE case_cells IS 'Table: CaseCells — the raw leaves of the DAG. One row per (study, stratum, treatment) combination recording the aggregate count of successes and total cases. Every derived fact in the model traces back to these numbers. Nothing above this row is a raw input.';
COMMENT ON COLUMN case_cells.case_cell_id IS 'Unique slug (e.g. kidney-1986-small-A).';
COMMENT ON COLUMN case_cells.study IS 'FK to the parent Study.';
COMMENT ON COLUMN case_cells.stratum_label IS 'The stratum this cell belongs to (matches Strata.StratumLabel).';
COMMENT ON COLUMN case_cells.treatment_label IS 'The treatment applied in this cell (matches Treatments.TreatmentLabel).';
COMMENT ON COLUMN case_cells.successes IS 'Number of patients in this cell who had a successful outcome. RAW INPUT — never derived.';
COMMENT ON COLUMN case_cells.cases IS 'Total number of patients in this cell. RAW INPUT — never derived.';

-- ----------------------------------------------------------------------------
-- StratumSummaries: Table: StratumSummaries — one row per (study, stratum, treatment). Computes the success rate WITHIN each stratum for each treatment. This is the stratified view that contradicts the pooled conclusion when a Simpson's Paradox reversal is present. Each row belongs to both a Stratum and a Treatment in the same Study.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stratum_summaries (
  stratum_summary_id                  TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-small-A).
);
ALTER TABLE stratum_summaries ADD COLUMN IF NOT EXISTS study TEXT;                                  -- FK to the parent Study.
ALTER TABLE stratum_summaries ADD COLUMN IF NOT EXISTS stratum_label TEXT;                          -- Which stratum (matches Strata.StratumLabel).
ALTER TABLE stratum_summaries ADD COLUMN IF NOT EXISTS treatment_label TEXT;                        -- Which treatment (matches Treatments.TreatmentLabel).
COMMENT ON TABLE stratum_summaries IS 'Table: StratumSummaries — one row per (study, stratum, treatment). Computes the success rate WITHIN each stratum for each treatment. This is the stratified view that contradicts the pooled conclusion when a Simpson''s Paradox reversal is present. Each row belongs to both a Stratum and a Treatment in the same Study.';
COMMENT ON COLUMN stratum_summaries.stratum_summary_id IS 'Unique slug (e.g. kidney-1986-small-A).';
COMMENT ON COLUMN stratum_summaries.study IS 'FK to the parent Study.';
COMMENT ON COLUMN stratum_summaries.stratum_label IS 'Which stratum (matches Strata.StratumLabel).';
COMMENT ON COLUMN stratum_summaries.treatment_label IS 'Which treatment (matches Treatments.TreatmentLabel).';

-- ----------------------------------------------------------------------------
-- ModelSummary: Table: ModelSummary — one row describing the epistemic coverage of this entire model instance. Aggregates across all TreatmentRankings to witness how many studies were examined, how many showed a full reversal, how many were explained, and the average paradox strength. The model holds a mirror to itself.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS model_summary (
  model_summary_id                    TEXT                 PRIMARY KEY          -- Unique identifier for this model instance.
);
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS synthetic_phase_count INTEGER;                   -- Number of parameter grid points in SyntheticPhase. Refreshed from vw_phase_diagram_summary by 05b-customize-data.sql.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS phase_diagram_complete BOOLEAN;                  -- TRUE when all five DistortionType cells are populated in the synthetic phase grid. Refreshed from vw_phase_diagram_summary by 05b.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS phase_taxonomy_coverage TEXT;                    -- Type counts across the synthetic phase grid. Refreshed from vw_phase_diagram_summary by 05b.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS high_imbalance_sign_flip_threshold NUMERIC;      -- max_stratum_imbalance cutoff for geometry-controlled domain screening (loop-66). Set from corpus median by customize SQL.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS economics_high_imbalance_sign_flip_count NUMERIC;-- Sign-flip count among economics studies with max_stratum_imbalance >= threshold.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS epidemiology_high_imbalance_sign_flip_rate NUMERIC;-- Sign-flip rate among high-imbalance epidemiology studies.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS legal_high_imbalance_sign_flip_rate NUMERIC;     -- Sign-flip rate among high-imbalance legal studies.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS sports_high_imbalance_sign_flip_rate NUMERIC;    -- Sign-flip rate among high-imbalance sports studies.
ALTER TABLE model_summary ADD COLUMN IF NOT EXISTS identity_cluster_witness_note TEXT;              -- Loop-80 identity layer witness rollup (customize SQL).
COMMENT ON TABLE model_summary IS 'Table: ModelSummary — one row describing the epistemic coverage of this entire model instance. Aggregates across all TreatmentRankings to witness how many studies were examined, how many showed a full reversal, how many were explained, and the average paradox strength. The model holds a mirror to itself.';
COMMENT ON COLUMN model_summary.model_summary_id IS 'Unique identifier for this model instance.';
COMMENT ON COLUMN model_summary.synthetic_phase_count IS 'Number of parameter grid points in SyntheticPhase. Refreshed from vw_phase_diagram_summary by 05b-customize-data.sql.';
COMMENT ON COLUMN model_summary.phase_diagram_complete IS 'TRUE when all five DistortionType cells are populated in the synthetic phase grid. Refreshed from vw_phase_diagram_summary by 05b.';
COMMENT ON COLUMN model_summary.phase_taxonomy_coverage IS 'Type counts across the synthetic phase grid. Refreshed from vw_phase_diagram_summary by 05b.';
COMMENT ON COLUMN model_summary.high_imbalance_sign_flip_threshold IS 'max_stratum_imbalance cutoff for geometry-controlled domain screening (loop-66). Set from corpus median by customize SQL.';
COMMENT ON COLUMN model_summary.economics_high_imbalance_sign_flip_count IS 'Sign-flip count among economics studies with max_stratum_imbalance >= threshold.';
COMMENT ON COLUMN model_summary.epidemiology_high_imbalance_sign_flip_rate IS 'Sign-flip rate among high-imbalance epidemiology studies.';
COMMENT ON COLUMN model_summary.legal_high_imbalance_sign_flip_rate IS 'Sign-flip rate among high-imbalance legal studies.';
COMMENT ON COLUMN model_summary.sports_high_imbalance_sign_flip_rate IS 'Sign-flip rate among high-imbalance sports studies.';
COMMENT ON COLUMN model_summary.identity_cluster_witness_note IS 'Loop-80 identity layer witness rollup (customize SQL).';

-- ----------------------------------------------------------------------------
-- StratumVariables: Table: StratumVariables — one row per study, naming the variable that defines the strata and describing its causal role. A confounder affects both treatment assignment AND outcome; a mediator is downstream of treatment; a contested variable is one where the causal role is disputed. IsConfounder is derived from these two boolean flags.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stratum_variables (
  stratum_variable_id                 TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-stone-size).
);
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS study TEXT;                                  -- FK to the parent Study.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS variable_name TEXT;                          -- The name of the stratifying variable (e.g. stone_size, department, age_group).
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS causal_role TEXT;                            -- The variable's causal role: 'confounder' (affects both assignment and outcome), 'mediator' (downstream of treatment), 'contested' (causal role disputed), 'unknown'.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS affects_treatment_assignment BOOLEAN;        -- TRUE if this variable causally influences which treatment a patient receives. Required for confounding.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS affects_outcome BOOLEAN;                     -- TRUE if this variable causally influences the outcome independently of treatment. Required for confounding.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS mechanism_note TEXT;                         -- Plain-language description of how this variable creates the confounding: why it affects both assignment and outcome.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS conditioning_risk TEXT;                      -- The causal hazard posed by conditioning on this variable. Values: confounder (safe to condition — removes bias), mediator (conditioning blocks the causal path of interest — harmful), collider (conditioning opens a spurious backdoor — harmful), proxy (conditioning on a noisy proxy of the true confounder — risky), none (no conditioning risk identified). NULL means unclassified.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS annotation_commit_hash TEXT;                 -- Full git SHA of the commit that first introduced this row's CausalRole/MechanismNote — derived via `git log -S` pickaxe search on this row's StratumVariableId (loop-98 audit-trail backfill). Real repo history, not a hand-entered label.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS annotation_commit_date DATE;                 -- ISO date (YYYY-MM-DD) of AnnotationCommitHash.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS annotation_commit_subject TEXT;              -- Git commit subject line of AnnotationCommitHash — the loop/change that landed this row's causal-role judgment call.
ALTER TABLE stratum_variables ADD COLUMN IF NOT EXISTS causal_role_ever_revised BOOLEAN;            -- TRUE if this row's CausalRole value differs across any two points in its git history (a real reclassification); FALSE if the value has been identical since AnnotationCommitHash. Computed once at loop-97 backfill via full-history diff, not re-derived live — re-run the backfill script after any future CausalRole edit to keep this accurate.
COMMENT ON TABLE stratum_variables IS 'Table: StratumVariables — one row per study, naming the variable that defines the strata and describing its causal role. A confounder affects both treatment assignment AND outcome; a mediator is downstream of treatment; a contested variable is one where the causal role is disputed. IsConfounder is derived from these two boolean flags.';
COMMENT ON COLUMN stratum_variables.stratum_variable_id IS 'Unique slug (e.g. kidney-1986-stone-size).';
COMMENT ON COLUMN stratum_variables.study IS 'FK to the parent Study.';
COMMENT ON COLUMN stratum_variables.variable_name IS 'The name of the stratifying variable (e.g. stone_size, department, age_group).';
COMMENT ON COLUMN stratum_variables.causal_role IS 'The variable''s causal role: ''confounder'' (affects both assignment and outcome), ''mediator'' (downstream of treatment), ''contested'' (causal role disputed), ''unknown''.';
COMMENT ON COLUMN stratum_variables.affects_treatment_assignment IS 'TRUE if this variable causally influences which treatment a patient receives. Required for confounding.';
COMMENT ON COLUMN stratum_variables.affects_outcome IS 'TRUE if this variable causally influences the outcome independently of treatment. Required for confounding.';
COMMENT ON COLUMN stratum_variables.mechanism_note IS 'Plain-language description of how this variable creates the confounding: why it affects both assignment and outcome.';
COMMENT ON COLUMN stratum_variables.conditioning_risk IS 'The causal hazard posed by conditioning on this variable. Values: confounder (safe to condition — removes bias), mediator (conditioning blocks the causal path of interest — harmful), collider (conditioning opens a spurious backdoor — harmful), proxy (conditioning on a noisy proxy of the true confounder — risky), none (no conditioning risk identified). NULL means unclassified.';
COMMENT ON COLUMN stratum_variables.annotation_commit_hash IS 'Full git SHA of the commit that first introduced this row''s CausalRole/MechanismNote — derived via `git log -S` pickaxe search on this row''s StratumVariableId (loop-98 audit-trail backfill). Real repo history, not a hand-entered label.';
COMMENT ON COLUMN stratum_variables.annotation_commit_date IS 'ISO date (YYYY-MM-DD) of AnnotationCommitHash.';
COMMENT ON COLUMN stratum_variables.annotation_commit_subject IS 'Git commit subject line of AnnotationCommitHash — the loop/change that landed this row''s causal-role judgment call.';
COMMENT ON COLUMN stratum_variables.causal_role_ever_revised IS 'TRUE if this row''s CausalRole value differs across any two points in its git history (a real reclassification); FALSE if the value has been identical since AnnotationCommitHash. Computed once at loop-97 backfill via full-history diff, not re-derived live — re-run the backfill script after any future CausalRole edit to keep this accurate.';

-- ----------------------------------------------------------------------------
-- TreatmentRankings: Table: TreatmentRankings — one row per treatment-pair comparison within a study. Derives the pooled winner, the per-stratum winner, and the IsReversal boolean. The paradox emerges here as a derived fact: IsReversal is true when the pooled winner and the per-stratum winner disagree.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS treatment_rankings (
  treatment_ranking_id                TEXT                 PRIMARY KEY          -- Unique slug (e.g. kidney-1986-A-vs-B).
);
ALTER TABLE treatment_rankings ADD COLUMN IF NOT EXISTS study TEXT;                                 -- FK to the parent Study.
ALTER TABLE treatment_rankings ADD COLUMN IF NOT EXISTS treatment_a TEXT;                           -- Label for the first treatment in the comparison (matches Treatments.TreatmentLabel).
ALTER TABLE treatment_rankings ADD COLUMN IF NOT EXISTS treatment_b TEXT;                           -- Label for the second treatment in the comparison.
ALTER TABLE treatment_rankings ADD COLUMN IF NOT EXISTS adjustment_rationale TEXT;                  -- Human-authored note explaining why AdjustmentAppropriate is TRUE or FALSE for this study. Covers mediator/collider hazards, contested causal roles, and cases where geometric correction is valid but causal interpretation is uncertain.
COMMENT ON TABLE treatment_rankings IS 'Table: TreatmentRankings — one row per treatment-pair comparison within a study. Derives the pooled winner, the per-stratum winner, and the IsReversal boolean. The paradox emerges here as a derived fact: IsReversal is true when the pooled winner and the per-stratum winner disagree.';
COMMENT ON COLUMN treatment_rankings.treatment_ranking_id IS 'Unique slug (e.g. kidney-1986-A-vs-B).';
COMMENT ON COLUMN treatment_rankings.study IS 'FK to the parent Study.';
COMMENT ON COLUMN treatment_rankings.treatment_a IS 'Label for the first treatment in the comparison (matches Treatments.TreatmentLabel).';
COMMENT ON COLUMN treatment_rankings.treatment_b IS 'Label for the second treatment in the comparison.';
COMMENT ON COLUMN treatment_rankings.adjustment_rationale IS 'Human-authored note explaining why AdjustmentAppropriate is TRUE or FALSE for this study. Covers mediator/collider hazards, contested causal roles, and cases where geometric correction is valid but causal interpretation is uncertain.';

-- ----------------------------------------------------------------------------
-- InvariantChecks: Table: InvariantChecks — one row per algebraic invariant across the 40-study validation corpus. PassCount and FailCount are populated by run_invariant_checks() in 05b-customize-data.sql. Any critical FailCount > 0 breaks the build.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invariant_checks (
  invariant_check_id                  TEXT                 PRIMARY KEY          -- Unique slug for this invariant (e.g. inv-balanced-alloc).
);
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS algebraic_statement TEXT;                     -- The mathematical assertion in compact symbolic form.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS natural_language TEXT;                        -- Plain-English statement of what property must hold and why it is an invariant of the model.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS source_table TEXT;                            -- The DAG table whose rows are checked (TreatmentRankings or StratumSummaries).
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS filter_expression TEXT;                       -- Condition selecting the universe of rows this invariant applies to. Empty means all rows.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS assertion_expression TEXT;                    -- The per-row condition that must be TRUE for every row in scope.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS sql_filter TEXT;                              -- Optional SQL WHERE clause that selects the universe of rows in scope for this invariant (e.g. distortion_type = 'D'). Empty string means all rows.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS sql_assertion TEXT;                           -- The SQL WHERE clause (without WHERE keyword) that counts PASSING rows from vw_treatment_rankings for this invariant. Used by run_invariant_checks() to evaluate each assertion dynamically from the rulebook table.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS pass_count INTEGER;                           -- Rows where the invariant holds. Populated by 05b-customize-data.sql from a live query against vw_treatment_rankings.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS fail_count INTEGER;                           -- Rows where the invariant is violated. Any FailCount > 0 is a build-breaking bug.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS severity TEXT;                                -- critical | warning — critical means any FailCount > 0 is a build-breaking bug.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS tradition_id TEXT;                            -- FK → ResearchTraditions.TraditionId. The tradition whose theoretical commitments this algebraic invariant protects — a failed invariant would falsify that tradition's key claim.
ALTER TABLE invariant_checks ADD COLUMN IF NOT EXISTS protects_conclusion TEXT;                     -- FK → Conclusions.ConclusionId. The conclusion whose witness depends on this invariant holding. If this invariant fails, that conclusion is undermined.
COMMENT ON TABLE invariant_checks IS 'Table: InvariantChecks — one row per algebraic invariant across the 40-study validation corpus. PassCount and FailCount are populated by run_invariant_checks() in 05b-customize-data.sql. Any critical FailCount > 0 breaks the build.';
COMMENT ON COLUMN invariant_checks.invariant_check_id IS 'Unique slug for this invariant (e.g. inv-balanced-alloc).';
COMMENT ON COLUMN invariant_checks.algebraic_statement IS 'The mathematical assertion in compact symbolic form.';
COMMENT ON COLUMN invariant_checks.natural_language IS 'Plain-English statement of what property must hold and why it is an invariant of the model.';
COMMENT ON COLUMN invariant_checks.source_table IS 'The DAG table whose rows are checked (TreatmentRankings or StratumSummaries).';
COMMENT ON COLUMN invariant_checks.filter_expression IS 'Condition selecting the universe of rows this invariant applies to. Empty means all rows.';
COMMENT ON COLUMN invariant_checks.assertion_expression IS 'The per-row condition that must be TRUE for every row in scope.';
COMMENT ON COLUMN invariant_checks.sql_filter IS 'Optional SQL WHERE clause that selects the universe of rows in scope for this invariant (e.g. distortion_type = ''D''). Empty string means all rows.';
COMMENT ON COLUMN invariant_checks.sql_assertion IS 'The SQL WHERE clause (without WHERE keyword) that counts PASSING rows from vw_treatment_rankings for this invariant. Used by run_invariant_checks() to evaluate each assertion dynamically from the rulebook table.';
COMMENT ON COLUMN invariant_checks.pass_count IS 'Rows where the invariant holds. Populated by 05b-customize-data.sql from a live query against vw_treatment_rankings.';
COMMENT ON COLUMN invariant_checks.fail_count IS 'Rows where the invariant is violated. Any FailCount > 0 is a build-breaking bug.';
COMMENT ON COLUMN invariant_checks.severity IS 'critical | warning — critical means any FailCount > 0 is a build-breaking bug.';
COMMENT ON COLUMN invariant_checks.tradition_id IS 'FK → ResearchTraditions.TraditionId. The tradition whose theoretical commitments this algebraic invariant protects — a failed invariant would falsify that tradition''s key claim.';
COMMENT ON COLUMN invariant_checks.protects_conclusion IS 'FK → Conclusions.ConclusionId. The conclusion whose witness depends on this invariant holding. If this invariant fails, that conclusion is undermined.';

-- ----------------------------------------------------------------------------
-- MaterializedEntities: Table: MaterializedEntities — governance record of every entity in this rulebook whose fields are principled materializations rather than live-calculated (per project CLAUDE.md: allowed only when the computation is genuinely expensive AND its upstream is sealed/stable, expressed as data in the rulebook itself, never as an ad-hoc application cache). Each row names the entity, the refresh contract, the refresh function that implements it, and the measured cost that justified materializing it. If this table's row for an entity were deleted, the entity's fields should still be regeneratable identically from the SSoT + the refresh function — that is the test for whether a materialization here is principled.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS materialized_entities (
  materialized_entity_id              TEXT                 PRIMARY KEY          -- Unique slug (e.g. mat-sweep-study-summary).
);
ALTER TABLE materialized_entities ADD COLUMN IF NOT EXISTS entity_table TEXT;                       -- The rulebook table whose fields are materialized (e.g. SweepStudySummary).
ALTER TABLE materialized_entities ADD COLUMN IF NOT EXISTS refresh_contract TEXT;                   -- eager-on-write | on-demand | scheduled — when the refresh function is invoked relative to writes on the upstream data.
ALTER TABLE materialized_entities ADD COLUMN IF NOT EXISTS refresh_function TEXT;                   -- The SQL function (in the customize-* override files) that recomputes this entity's materialized fields from its upstream SSoT tables.
ALTER TABLE materialized_entities ADD COLUMN IF NOT EXISTS upstream_tables TEXT;                    -- Comma-separated list of the tables this materialization is derived from — its sealed/stable upstream.
ALTER TABLE materialized_entities ADD COLUMN IF NOT EXISTS justification TEXT;                      -- The measured cost or evidence that justified materializing this entity instead of leaving it as a live calculated/aggregation field.
COMMENT ON TABLE materialized_entities IS 'Table: MaterializedEntities — governance record of every entity in this rulebook whose fields are principled materializations rather than live-calculated (per project CLAUDE.md: allowed only when the computation is genuinely expensive AND its upstream is sealed/stable, expressed as data in the rulebook itself, never as an ad-hoc application cache). Each row names the entity, the refresh contract, the refresh function that implements it, and the measured cost that justified materializing it. If this table''s row for an entity were deleted, the entity''s fields should still be regeneratable identically from the SSoT + the refresh function — that is the test for whether a materialization here is principled.';
COMMENT ON COLUMN materialized_entities.materialized_entity_id IS 'Unique slug (e.g. mat-sweep-study-summary).';
COMMENT ON COLUMN materialized_entities.entity_table IS 'The rulebook table whose fields are materialized (e.g. SweepStudySummary).';
COMMENT ON COLUMN materialized_entities.refresh_contract IS 'eager-on-write | on-demand | scheduled — when the refresh function is invoked relative to writes on the upstream data.';
COMMENT ON COLUMN materialized_entities.refresh_function IS 'The SQL function (in the customize-* override files) that recomputes this entity''s materialized fields from its upstream SSoT tables.';
COMMENT ON COLUMN materialized_entities.upstream_tables IS 'Comma-separated list of the tables this materialization is derived from — its sealed/stable upstream.';
COMMENT ON COLUMN materialized_entities.justification IS 'The measured cost or evidence that justified materializing this entity instead of leaving it as a live calculated/aggregation field.';

-- ----------------------------------------------------------------------------
-- Methodology: Table: Methodology — the first-principles process used to build this domain model. Each row documents one methodological axiom or step. Together these rows let a reader (or an LLM) reconstruct why the model is shaped the way it is, and re-apply the same process to a new domain.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS methodology (
  methodology_id                      TEXT                 PRIMARY KEY          -- Unique slug (e.g. method-01-cmcc, method-02-dag-first).
);
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS phase TEXT;                                        -- Broad phase: axiom | decomposition | derivation | hydration | validation | taxonomy | conclusion
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS title TEXT;                                        -- Short title of the methodological principle or step.
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS statement TEXT;                                    -- One-to-three sentence statement of the principle, precise enough to be applied or falsified.
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS why_it_matters TEXT;                               -- Why this step or principle is load-bearing for this model — what breaks if you skip it.
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS illustrated_by_loop TEXT;                          -- LoopId(s) where this principle was concretely demonstrated (comma-separated).
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS tradition_id TEXT;                                 -- FK → ResearchTraditions.TraditionId. The scholarly tradition that introduced or most relies on this methodological approach.
ALTER TABLE methodology ADD COLUMN IF NOT EXISTS pioneering_researcher TEXT;                        -- FK → Researchers.ResearcherId. The researcher most associated with developing or popularising this methodological principle in the Simpson's Paradox context.
COMMENT ON TABLE methodology IS 'Table: Methodology — the first-principles process used to build this domain model. Each row documents one methodological axiom or step. Together these rows let a reader (or an LLM) reconstruct why the model is shaped the way it is, and re-apply the same process to a new domain.';
COMMENT ON COLUMN methodology.methodology_id IS 'Unique slug (e.g. method-01-cmcc, method-02-dag-first).';
COMMENT ON COLUMN methodology.phase IS 'Broad phase: axiom | decomposition | derivation | hydration | validation | taxonomy | conclusion';
COMMENT ON COLUMN methodology.title IS 'Short title of the methodological principle or step.';
COMMENT ON COLUMN methodology.statement IS 'One-to-three sentence statement of the principle, precise enough to be applied or falsified.';
COMMENT ON COLUMN methodology.why_it_matters IS 'Why this step or principle is load-bearing for this model — what breaks if you skip it.';
COMMENT ON COLUMN methodology.illustrated_by_loop IS 'LoopId(s) where this principle was concretely demonstrated (comma-separated).';
COMMENT ON COLUMN methodology.tradition_id IS 'FK → ResearchTraditions.TraditionId. The scholarly tradition that introduced or most relies on this methodological approach.';
COMMENT ON COLUMN methodology.pioneering_researcher IS 'FK → Researchers.ResearcherId. The researcher most associated with developing or popularising this methodological principle in the Simpson''s Paradox context.';

-- ----------------------------------------------------------------------------
-- Conclusions: Table: Conclusions — the substantive epistemic findings that this model has produced or is designed to produce. Each row is one conclusion: a claim about the domain, about the instrument, or about the methodology that is either already witnessed or is the target of a planned loop.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS conclusions (
  conclusion_id                       TEXT                 PRIMARY KEY          -- Unique slug (e.g. conc-01-paradox-is-derived).
);
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS category TEXT;                                     -- domain | instrument | methodology | open-question | corpus-theorem
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS status TEXT;                                       -- witnessed | planned | open
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS report_tier TEXT;                                  -- critical | supporting | transient — controls how much space this conclusion gets in the generated PDF/summary report. critical = full section with evidence + chart; supporting = 1-2 line bullet; transient = folded into a single compact list.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS validating_hypothesis TEXT;                        -- FK → DiscoveryHypotheses.HypothesisId. The pre-registered hypothesis whose live DiscoveryFindings.IsConfirmed value is the current-truth check for this conclusion — set on theorem/corpus-theorem conclusions so a report can distinguish a conclusion's archived prose (may say 'Proved') from its live status (may since be contradicted by corpus growth). Null when no single hypothesis tests this exact claim.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS title TEXT;                                        -- One-line statement of the conclusion.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS evidence TEXT;                                     -- The specific DB query result, loop outcome, or argument that establishes or will establish this conclusion.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS witnessed_in_loop TEXT;                            -- LoopId where this conclusion was first witnessed (if status=witnessed).
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS target_loop TEXT;                                  -- LoopId that is designed to witness this conclusion (if status=planned).
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS tradition_id TEXT;                                 -- FK → ResearchTraditions.TraditionId. The tradition whose theoretical framework this conclusion primarily vindicates, refines, or challenges.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS researcher_id TEXT;                                -- FK → Researchers.ResearcherId. The researcher whose specific claim, definition, or framework this conclusion directly affirms.
ALTER TABLE conclusions ADD COLUMN IF NOT EXISTS challenges_researcher TEXT;                        -- FK → Researchers.ResearcherId. A researcher whose position this conclusion refutes or qualifies (e.g. conc-03 refutes Blyth's unanimity criterion as the primary definition).
COMMENT ON TABLE conclusions IS 'Table: Conclusions — the substantive epistemic findings that this model has produced or is designed to produce. Each row is one conclusion: a claim about the domain, about the instrument, or about the methodology that is either already witnessed or is the target of a planned loop.';
COMMENT ON COLUMN conclusions.conclusion_id IS 'Unique slug (e.g. conc-01-paradox-is-derived).';
COMMENT ON COLUMN conclusions.category IS 'domain | instrument | methodology | open-question | corpus-theorem';
COMMENT ON COLUMN conclusions.status IS 'witnessed | planned | open';
COMMENT ON COLUMN conclusions.report_tier IS 'critical | supporting | transient — controls how much space this conclusion gets in the generated PDF/summary report. critical = full section with evidence + chart; supporting = 1-2 line bullet; transient = folded into a single compact list.';
COMMENT ON COLUMN conclusions.validating_hypothesis IS 'FK → DiscoveryHypotheses.HypothesisId. The pre-registered hypothesis whose live DiscoveryFindings.IsConfirmed value is the current-truth check for this conclusion — set on theorem/corpus-theorem conclusions so a report can distinguish a conclusion''s archived prose (may say ''Proved'') from its live status (may since be contradicted by corpus growth). Null when no single hypothesis tests this exact claim.';
COMMENT ON COLUMN conclusions.title IS 'One-line statement of the conclusion.';
COMMENT ON COLUMN conclusions.evidence IS 'The specific DB query result, loop outcome, or argument that establishes or will establish this conclusion.';
COMMENT ON COLUMN conclusions.witnessed_in_loop IS 'LoopId where this conclusion was first witnessed (if status=witnessed).';
COMMENT ON COLUMN conclusions.target_loop IS 'LoopId that is designed to witness this conclusion (if status=planned).';
COMMENT ON COLUMN conclusions.tradition_id IS 'FK → ResearchTraditions.TraditionId. The tradition whose theoretical framework this conclusion primarily vindicates, refines, or challenges.';
COMMENT ON COLUMN conclusions.researcher_id IS 'FK → Researchers.ResearcherId. The researcher whose specific claim, definition, or framework this conclusion directly affirms.';
COMMENT ON COLUMN conclusions.challenges_researcher IS 'FK → Researchers.ResearcherId. A researcher whose position this conclusion refutes or qualifies (e.g. conc-03 refutes Blyth''s unanimity criterion as the primary definition).';

-- ----------------------------------------------------------------------------
-- UIScreens: Table: UIScreens — the canonical screens that comprise the Simpson's Paradox Explorer UI. Each row defines one screen: its purpose, its primary data source (which rulebook view it reads), and the user action it supports. A developer can reconstruct the full UI from this table without any prior knowledge of the application.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ui_screens (
  screen_id                           TEXT                 PRIMARY KEY          -- Unique slug (e.g. screen-01-study-list).
);
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS title TEXT;                                         -- Human-readable screen title shown in the UI.
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS route TEXT;                                         -- URL path pattern (e.g. /, /study/:studyId, /compare).
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS primary_entity TEXT;                                -- The main rulebook entity this screen reads from (the vw_* view name without prefix).
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS purpose TEXT;                                       -- One sentence: what a user can learn or do on this screen.
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS key_fields TEXT;                                    -- Comma-separated list of the most important fields displayed on this screen.
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS user_action TEXT;                                   -- Primary user action available on this screen (e.g. select a study, drill into a stratum).
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS tradition_id TEXT;                                  -- FK → ResearchTraditions.TraditionId. The scholarly tradition whose lens this screen primarily serves — determines which framing language and which fields are most prominent.
ALTER TABLE ui_screens ADD COLUMN IF NOT EXISTS primary_conclusion TEXT;                            -- FK → Conclusions.ConclusionId. The conclusion this screen most directly visualises or communicates to the user.
COMMENT ON TABLE ui_screens IS 'Table: UIScreens — the canonical screens that comprise the Simpson''s Paradox Explorer UI. Each row defines one screen: its purpose, its primary data source (which rulebook view it reads), and the user action it supports. A developer can reconstruct the full UI from this table without any prior knowledge of the application.';
COMMENT ON COLUMN ui_screens.screen_id IS 'Unique slug (e.g. screen-01-study-list).';
COMMENT ON COLUMN ui_screens.title IS 'Human-readable screen title shown in the UI.';
COMMENT ON COLUMN ui_screens.route IS 'URL path pattern (e.g. /, /study/:studyId, /compare).';
COMMENT ON COLUMN ui_screens.primary_entity IS 'The main rulebook entity this screen reads from (the vw_* view name without prefix).';
COMMENT ON COLUMN ui_screens.purpose IS 'One sentence: what a user can learn or do on this screen.';
COMMENT ON COLUMN ui_screens.key_fields IS 'Comma-separated list of the most important fields displayed on this screen.';
COMMENT ON COLUMN ui_screens.user_action IS 'Primary user action available on this screen (e.g. select a study, drill into a stratum).';
COMMENT ON COLUMN ui_screens.tradition_id IS 'FK → ResearchTraditions.TraditionId. The scholarly tradition whose lens this screen primarily serves — determines which framing language and which fields are most prominent.';
COMMENT ON COLUMN ui_screens.primary_conclusion IS 'FK → Conclusions.ConclusionId. The conclusion this screen most directly visualises or communicates to the user.';

-- ----------------------------------------------------------------------------
-- UIComponents: Table: UIComponents — the reusable visual building blocks used across UIScreens. Each row defines one component: what it renders, which entity it reads, and what props it requires. A developer can implement the full UI by composing these components onto the screens defined in UIScreens.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ui_components (
  component_id                        TEXT                 PRIMARY KEY          -- Unique slug (e.g. comp-01-distortion-badge).
);
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS component_name TEXT;                             -- Code-level component name (PascalCase, e.g. DistortionBadge).
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS used_on_screens TEXT;                            -- Comma-separated ScreenIds where this component appears.
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS primary_entity TEXT;                             -- The rulebook entity this component reads (the vw_* view).
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS description TEXT;                                -- What this component renders and what decisions a developer must make to implement it.
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS required_fields TEXT;                            -- Comma-separated rulebook fields this component must receive as props.
ALTER TABLE ui_components ADD COLUMN IF NOT EXISTS visual_spec TEXT;                                -- Plain-English description of the visual output: shape, color coding, interactivity.
COMMENT ON TABLE ui_components IS 'Table: UIComponents — the reusable visual building blocks used across UIScreens. Each row defines one component: what it renders, which entity it reads, and what props it requires. A developer can implement the full UI by composing these components onto the screens defined in UIScreens.';
COMMENT ON COLUMN ui_components.component_id IS 'Unique slug (e.g. comp-01-distortion-badge).';
COMMENT ON COLUMN ui_components.component_name IS 'Code-level component name (PascalCase, e.g. DistortionBadge).';
COMMENT ON COLUMN ui_components.used_on_screens IS 'Comma-separated ScreenIds where this component appears.';
COMMENT ON COLUMN ui_components.primary_entity IS 'The rulebook entity this component reads (the vw_* view).';
COMMENT ON COLUMN ui_components.description IS 'What this component renders and what decisions a developer must make to implement it.';
COMMENT ON COLUMN ui_components.required_fields IS 'Comma-separated rulebook fields this component must receive as props.';
COMMENT ON COLUMN ui_components.visual_spec IS 'Plain-English description of the visual output: shape, color coding, interactivity.';

-- ----------------------------------------------------------------------------
-- InstrumentSpec: Table: InstrumentSpec — the complete specification of the Simpson's Paradox classification instrument. One row per component: required input fields, derived coordinates, classification outputs, and adapter requirements. Every row is machine-verifiable against the 238-study corpus. This table is the distillation of loops 1–25 into a reusable tool.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS instrument_spec (
  spec_id                             TEXT                 PRIMARY KEY          -- Unique identifier for this instrument component.
);
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS component_type TEXT;                           -- input | derived | classification | adapter-requirement
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS field_name TEXT;                               -- The field or variable name in the DAG.
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS data_type TEXT;                                -- integer | decimal | boolean | string | categorical
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS source_table TEXT;                             -- The DAG table where this field is computed or stored.
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS formula TEXT;                                  -- The ERB formula or derivation rule for this component.
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS natural_language TEXT;                         -- Plain-English statement of what this component represents or requires.
ALTER TABLE instrument_spec ADD COLUMN IF NOT EXISTS adapter_note TEXT;                             -- What a researcher must supply or verify to satisfy this component when hydrating a new study.
COMMENT ON TABLE instrument_spec IS 'Table: InstrumentSpec — the complete specification of the Simpson''s Paradox classification instrument. One row per component: required input fields, derived coordinates, classification outputs, and adapter requirements. Every row is machine-verifiable against the 238-study corpus. This table is the distillation of loops 1–25 into a reusable tool.';
COMMENT ON COLUMN instrument_spec.spec_id IS 'Unique identifier for this instrument component.';
COMMENT ON COLUMN instrument_spec.component_type IS 'input | derived | classification | adapter-requirement';
COMMENT ON COLUMN instrument_spec.field_name IS 'The field or variable name in the DAG.';
COMMENT ON COLUMN instrument_spec.data_type IS 'integer | decimal | boolean | string | categorical';
COMMENT ON COLUMN instrument_spec.source_table IS 'The DAG table where this field is computed or stored.';
COMMENT ON COLUMN instrument_spec.formula IS 'The ERB formula or derivation rule for this component.';
COMMENT ON COLUMN instrument_spec.natural_language IS 'Plain-English statement of what this component represents or requires.';
COMMENT ON COLUMN instrument_spec.adapter_note IS 'What a researcher must supply or verify to satisfy this component when hydrating a new study.';

-- ----------------------------------------------------------------------------
-- AllocationSweep: Table: AllocationSweep — parametric sweep of treatment-A allocation fraction within each study's most confounded stratum (see SweepStudyConfig). Ten fractions from 0.05 to 0.95 per study. SweepCorrectedGap is invariant; SweepPooledGap wanders.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS allocation_sweep (
  sweep_id                            TEXT                 PRIMARY KEY          -- Unique row identifier: <study>-f<pct> where pct is AllocFractionA*100.
);
ALTER TABLE allocation_sweep ADD COLUMN IF NOT EXISTS study_id TEXT;                                -- The study being swept — all 238 studies in the corpus.
ALTER TABLE allocation_sweep ADD COLUMN IF NOT EXISTS alloc_fraction_a NUMERIC;                     -- Fraction of the sweep-stratum cases assigned to treatment A. Ranges from 0.05 to 0.95. The sweep stratum is the one whose allocation was most confounded in the original study.
COMMENT ON TABLE allocation_sweep IS 'Table: AllocationSweep — parametric sweep of treatment-A allocation fraction within each study''s most confounded stratum (see SweepStudyConfig). Ten fractions from 0.05 to 0.95 per study. SweepCorrectedGap is invariant; SweepPooledGap wanders.';
COMMENT ON COLUMN allocation_sweep.sweep_id IS 'Unique row identifier: <study>-f<pct> where pct is AllocFractionA*100.';
COMMENT ON COLUMN allocation_sweep.study_id IS 'The study being swept — all 238 studies in the corpus.';
COMMENT ON COLUMN allocation_sweep.alloc_fraction_a IS 'Fraction of the sweep-stratum cases assigned to treatment A. Ranges from 0.05 to 0.95. The sweep stratum is the one whose allocation was most confounded in the original study.';

-- ----------------------------------------------------------------------------
-- SweepStudySummary: Table: SweepStudySummary
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sweep_study_summary (
  sweep_study_id                      TEXT                 PRIMARY KEY          -- FK to Studies.StudyId. One row per study in the AllocationSweep.
);
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS corrected_gap_constant NUMERIC;            -- Principled materialization (refresh_sweep_study_summary(), 03b/05b customize SQL). The allocation-free corrected gap for this study = MINIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). Upstream (AllocationSweep, SweepStudyConfig) is sealed/stable per build; recomputing this per-row via nested calc_* calls was measured to fan out to 22.5s for a 242-study corpus scan with zero memoization — materialized here instead of left as a live calculated field. See MaterializedEntities.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_corrected_gap_max NUMERIC;           -- Principled materialization (refresh_sweep_study_summary()). Maximum SweepCorrectedGap across all allocation fractions for this study = MAXIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_corrected_gap_min NUMERIC;           -- Principled materialization (refresh_sweep_study_summary()). Minimum SweepCorrectedGap across all allocation fractions for this study = MINIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_corrected_gap_range NUMERIC;         -- Principled materialization (refresh_sweep_study_summary()). Range of SweepCorrectedGap across the sweep = SweepCorrectedGapMax - SweepCorrectedGapMin. Should be effectively zero (< 0.0001) for all studies if CorrectedGap is truly allocation-free. See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_pooled_gap_max NUMERIC;              -- Principled materialization (refresh_sweep_study_summary()). Maximum SweepPooledGap across all allocation fractions for this study = MAXIFS(AllocationSweep[SweepPooledGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_pooled_gap_min NUMERIC;              -- Principled materialization (refresh_sweep_study_summary()). Minimum SweepPooledGap across all allocation fractions for this study = MINIFS(AllocationSweep[SweepPooledGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS sweep_pooled_gap_range NUMERIC;            -- Principled materialization (refresh_sweep_study_summary()). Range of SweepPooledGap across the sweep = SweepPooledGapMax - SweepPooledGapMin. Should be large for Type A/B studies (pooled gap wanders) and smaller for Type D (balanced allocation = less wandering). See CorrectedGapConstant for why this is materialized rather than calculated.
ALTER TABLE sweep_study_summary ADD COLUMN IF NOT EXISTS pooled_gap_crosses_zero BOOLEAN;           -- Principled materialization (refresh_sweep_study_summary()). TRUE when SweepPooledGapMin < 0 and SweepPooledGapMax > 0 — the pooled gap changes sign somewhere in the sweep, meaning the paradox can be created or destroyed by pure allocation. See CorrectedGapConstant for why this is materialized rather than calculated.
COMMENT ON COLUMN sweep_study_summary.sweep_study_id IS 'FK to Studies.StudyId. One row per study in the AllocationSweep.';
COMMENT ON COLUMN sweep_study_summary.corrected_gap_constant IS 'Principled materialization (refresh_sweep_study_summary(), 03b/05b customize SQL). The allocation-free corrected gap for this study = MINIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). Upstream (AllocationSweep, SweepStudyConfig) is sealed/stable per build; recomputing this per-row via nested calc_* calls was measured to fan out to 22.5s for a 242-study corpus scan with zero memoization — materialized here instead of left as a live calculated field. See MaterializedEntities.';
COMMENT ON COLUMN sweep_study_summary.sweep_corrected_gap_max IS 'Principled materialization (refresh_sweep_study_summary()). Maximum SweepCorrectedGap across all allocation fractions for this study = MAXIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.sweep_corrected_gap_min IS 'Principled materialization (refresh_sweep_study_summary()). Minimum SweepCorrectedGap across all allocation fractions for this study = MINIFS(AllocationSweep[SweepCorrectedGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.sweep_corrected_gap_range IS 'Principled materialization (refresh_sweep_study_summary()). Range of SweepCorrectedGap across the sweep = SweepCorrectedGapMax - SweepCorrectedGapMin. Should be effectively zero (< 0.0001) for all studies if CorrectedGap is truly allocation-free. See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.sweep_pooled_gap_max IS 'Principled materialization (refresh_sweep_study_summary()). Maximum SweepPooledGap across all allocation fractions for this study = MAXIFS(AllocationSweep[SweepPooledGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.sweep_pooled_gap_min IS 'Principled materialization (refresh_sweep_study_summary()). Minimum SweepPooledGap across all allocation fractions for this study = MINIFS(AllocationSweep[SweepPooledGap], AllocationSweep[StudyId], SweepStudyId). See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.sweep_pooled_gap_range IS 'Principled materialization (refresh_sweep_study_summary()). Range of SweepPooledGap across the sweep = SweepPooledGapMax - SweepPooledGapMin. Should be large for Type A/B studies (pooled gap wanders) and smaller for Type D (balanced allocation = less wandering). See CorrectedGapConstant for why this is materialized rather than calculated.';
COMMENT ON COLUMN sweep_study_summary.pooled_gap_crosses_zero IS 'Principled materialization (refresh_sweep_study_summary()). TRUE when SweepPooledGapMin < 0 and SweepPooledGapMax > 0 — the pooled gap changes sign somewhere in the sweep, meaning the paradox can be created or destroyed by pure allocation. See CorrectedGapConstant for why this is materialized rather than calculated.';

-- ----------------------------------------------------------------------------
-- ResearchTraditions: Table: ResearchTraditions — the six scholarly lineages that have engaged with Simpson's Paradox. Each row is a named intellectual tradition, not a specific paper or result.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_traditions (
  tradition_id                        TEXT                 PRIMARY KEY          -- Slug identifier, e.g. tradition-historical.
);
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS name TEXT;                                 -- Short display name for the tradition.
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS era TEXT;                                  -- Approximate active period, e.g. "1899–1972".
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS core_concern TEXT;                         -- The central question this tradition asks about the paradox.
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS primary_venue TEXT;                        -- Where this tradition publishes (journal, conference, book series).
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS key_claim TEXT;                            -- The tradition's signature thesis or resolution strategy.
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS open_question TEXT;                        -- What this tradition leaves unresolved or contested.
ALTER TABLE research_traditions ADD COLUMN IF NOT EXISTS verified_by_deep_research BOOLEAN;         -- True if the 2026-06-28 adversarial deep-research pass confirmed the tradition at high confidence.
