$$ LANGUAGE sql STABLE;

-- calc_studies_total_cases
-- Field: Studies.TotalCases
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_studies_total_cases(p_study_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((cases)::numeric), 0) FROM case_cells WHERE study = p_study_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_studies_cell_count
-- Field: Studies.CellCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_studies_cell_count(p_study_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM case_cells WHERE study = (SELECT NULLIF(study_id, '') FROM studies WHERE study_id = p_study_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_studies_ingestion_cell_parity
-- Field: Studies.IngestionCellParity
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_studies_ingestion_cell_parity(p_study_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((((calc_treatment_rankings_stratum_count((SELECT treatment_ranking_id FROM treatment_rankings WHERE study = ((SELECT NULLIF(study_id, '') FROM studies WHERE study_id = p_study_id))::text))))::NUMERIC >= 2 AND calc_studies_cell_count(p_study_id) = (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((calc_treatment_rankings_stratum_count((SELECT treatment_ranking_id FROM treatment_rankings WHERE study = ((SELECT NULLIF(study_id, '') FROM studies WHERE study_id = p_study_id))::text)))) AS v) __safe_numeric), 0) * COALESCE(2, 0))));
$$ LANGUAGE sql STABLE;

-- calc_studies_ingestion_compliance
-- Field: Studies.IngestionCompliance
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_studies_ingestion_compliance(p_study_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_synthetic FROM studies WHERE study_id = p_study_id), FALSE) THEN ('exempt-synthetic')::text ELSE (CASE WHEN (calc_studies_ingestion_cell_parity(p_study_id) AND ((SELECT variable_name::text FROM stratum_variables WHERE study = ((SELECT NULLIF(study_id, '') FROM studies WHERE study_id = p_study_id))::text)) IS NOT NULL) THEN ('all')::text ELSE ('partial')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_studies_valid_time_midpoint
-- Field: Studies.ValidTimeMidpoint
-- Type: calculated | DataType: float | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_studies_valid_time_midpoint(p_study_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN ((SELECT valid_time_start FROM studies WHERE study_id = p_study_id) IS NOT NULL AND (SELECT valid_time_end FROM studies WHERE study_id = p_study_id) IS NOT NULL) THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT valid_time_start FROM studies WHERE study_id = p_study_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT valid_time_end FROM studies WHERE study_id = p_study_id)) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0) / NULLIF(COALESCE(2, 0), 0)))::text ELSE ((SELECT publication_year FROM studies WHERE study_id = p_study_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_studies_valid_time_decade
-- Field: Studies.ValidTimeDecade
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_studies_valid_time_decade(p_study_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_studies_valid_time_midpoint(p_study_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN NULL ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) / NULLIF(COALESCE(10, 0), 0)))::NUMERIC)) AS v) __safe_numeric), 0) * COALESCE(10, 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

