-- calc_model_summary_study_count
-- Field: ModelSummary.StudyCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_summary_study_count(p_model_summary_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_model_summary_reversal_count(p_model_summary_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_model_summary_non_reversal_count(p_model_summary_id)) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

