RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_treatment_rankings_paradox_strength(treatment_ranking_id))::numeric), 0) FROM treatment_rankings WHERE treatment_a = 'A'))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_model_summary_avg_paradox_strength
