  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_pooled_rate_a(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_pooled_rate_b(p_treatment_ranking_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1) IS NULL OR (SELECT val FROM __erb_dedup_v2) IS NULL) THEN ('')::text ELSE (CASE WHEN (ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v2)) AS v) __safe_numeric), 0))))::NUMERIC < 0.0000001 THEN ('tie')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v1) > (SELECT val FROM __erb_dedup_v2) THEN ((SELECT NULLIF(treatment_a, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id))::text ELSE ((SELECT NULLIF(treatment_b, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id))::text END)::text END)::text END)::text;
