-- calc_treatment_rankings_distortion_type
-- Field: TreatmentRankings.DistortionType
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_treatment_rankings_distortion_type(p_treatment_ranking_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_allocation_distortion(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_is_sign_flip(p_treatment_ranking_id) AS val), __erb_dedup_v3 AS (SELECT calc_treatment_rankings_signed_pooled_gap(p_treatment_ranking_id) AS val), __erb_dedup_v4 AS (SELECT calc_treatment_rankings_corrected_gap(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN ('')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v2) THEN (CASE WHEN calc_treatment_rankings_is_stratum_unanimous(p_treatment_ranking_id) THEN ('A')::text ELSE ('B')::text END)::text ELSE (CASE WHEN (NOT ((SELECT val FROM __erb_dedup_v2)) AND ((SELECT val FROM __erb_dedup_v1))::NUMERIC > 0.01 AND ABS((SELECT val FROM __erb_dedup_v3)) > (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v4))) AS v) __safe_numeric), 0) + COALESCE(0.001, 0))) THEN ('C+')::text ELSE (CASE WHEN (NOT ((SELECT val FROM __erb_dedup_v2)) AND ((SELECT val FROM __erb_dedup_v1))::NUMERIC > 0.01 AND ABS((SELECT val FROM __erb_dedup_v3)) < (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v4))) AS v) __safe_numeric), 0) - COALESCE(0.001, 0))) THEN ('C-')::text ELSE ('D')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_policy_implication
-- Field: TreatmentRankings.PolicyImplication
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_treatment_rankings_policy_implication(p_treatment_ranking_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_distortion_type(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN ('')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v1) = 'A' THEN ('stratify-immediately')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v1) = 'B' THEN ('investigate-confounder')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1) = 'C+' OR (SELECT val FROM __erb_dedup_v1) = 'C-') THEN ('check-allocation-bias')::text ELSE ('pooled-analysis-trustworthy')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_corrected_gap
-- Field: TreatmentRankings.CorrectedGap
