$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_allocation_direction
-- Field: TreatmentRankings.AllocationDirection
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_treatment_rankings_allocation_direction(p_treatment_ranking_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_corrected_gap(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_signed_pooled_gap(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN ('')::text ELSE (CASE WHEN calc_treatment_rankings_is_sign_flip(p_treatment_ranking_id) THEN ('reversal')::text ELSE (CASE WHEN ABS((SELECT val FROM __erb_dedup_v2)) > (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v1))) AS v) __safe_numeric), 0) + COALESCE(0.001, 0)) THEN ('amplification')::text ELSE (CASE WHEN ABS((SELECT val FROM __erb_dedup_v2)) < (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v1))) AS v) __safe_numeric), 0) - COALESCE(0.001, 0)) THEN ('compression')::text ELSE ('neutral')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_signal_purity
-- Field: TreatmentRankings.SignalPurity
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_signal_purity(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_corrected_gap(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_allocation_distortion(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN NULL ELSE (CASE WHEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v1))) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v2)) AS v) __safe_numeric), 0)))::NUMERIC = 0 THEN (1)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v1))) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v1))) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v2)) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0), 0)))::text END)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_latent_flip_potential
-- Field: TreatmentRankings.LatentFlipPotential
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_treatment_rankings_latent_flip_potential(p_treatment_ranking_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_distortion_type(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN NULL ELSE (((SELECT val FROM __erb_dedup_v1) = 'D' AND calc_treatment_rankings_pooled_gap_crosses_zero(p_treatment_ranking_id) = TRUE))::text END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_allocation_fragility
-- Field: TreatmentRankings.AllocationFragility
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_allocation_fragility(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_sweep_pooled_gap_range(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_pooled_gap(p_treatment_ranking_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1) IS NULL OR (SELECT val FROM __erb_dedup_v2) IS NULL OR ((SELECT val FROM __erb_dedup_v2))::NUMERIC = 0) THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v2))) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_max_stratum_imbalance
-- Field: TreatmentRankings.MaxStratumImbalance
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_max_stratum_imbalance(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MAX((calc_stratum_summaries_abs_allocation_bias(stratum_summary_id))::numeric), 0) FROM stratum_summaries WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND treatment_label = 'A'))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_max_stratum_gap
-- Field: TreatmentRankings.MaxStratumGap
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_max_stratum_gap(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MAX((calc_stratum_summaries_abs_stratum_gap(stratum_summary_id))::numeric), 0) FROM stratum_summaries WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND treatment_label = 'A'))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_is_sweep_fragile
-- Field: TreatmentRankings.IsSweepFragile
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_treatment_rankings_is_sweep_fragile(p_treatment_ranking_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_treatment_rankings_distortion_type(p_treatment_ranking_id) = 'D' AND (calc_treatment_rankings_signal_purity(p_treatment_ranking_id))::NUMERIC = 1 AND (calc_treatment_rankings_allocation_distortion(p_treatment_ranking_id))::NUMERIC = 0 AND (calc_treatment_rankings_sweep_pooled_gap_range(p_treatment_ranking_id))::NUMERIC > 0.3 AND (calc_treatment_rankings_allocation_fragility(p_treatment_ranking_id))::NUMERIC >= 10));
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_is_latent_only_flip
-- Field: TreatmentRankings.IsLatentOnlyFlip
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_treatment_rankings_is_latent_only_flip(p_treatment_ranking_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_pooled_gap_crosses_zero(p_treatment_ranking_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN NULL ELSE (((SELECT val FROM __erb_dedup_v1) = TRUE AND calc_treatment_rankings_is_sign_flip(p_treatment_ranking_id) = FALSE))::text END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_confirmed_causal_role_count
-- Field: TreatmentRankings.ConfirmedCausalRoleCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_treatment_rankings_confirmed_causal_role_count(p_treatment_ranking_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM stratum_variables WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND causal_role = 'confounder'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_mediator_risk_count
-- Field: TreatmentRankings.MediatorRiskCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_treatment_rankings_mediator_risk_count(p_treatment_ranking_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM stratum_variables WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND conditioning_risk = 'mediator')) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM stratum_variables WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND conditioning_risk = 'collider')) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_contested_stratum_count
-- Field: TreatmentRankings.ContestedStratumCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_treatment_rankings_contested_stratum_count(p_treatment_ranking_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM stratum_variables WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND causal_role = 'contested'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_unknown_causal_role_count
-- Field: TreatmentRankings.UnknownCausalRoleCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_treatment_rankings_unknown_causal_role_count(p_treatment_ranking_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM stratum_variables WHERE study = (SELECT NULLIF(study, '') FROM treatment_rankings WHERE treatment_ranking_id = p_treatment_ranking_id) AND causal_role = 'unknown'))::integer;
