-- calc_treatment_rankings_distortion_ratio
-- Field: TreatmentRankings.DistortionRatio
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_distortion_ratio(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_weighted_stratum_gap_sum(p_treatment_ranking_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_treatment_rankings_signed_pooled_gap(p_treatment_ranking_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_screening_tier
-- Field: TreatmentRankings.ScreeningTier
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_treatment_rankings_screening_tier(p_treatment_ranking_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_distortion_type(p_treatment_ranking_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1) = 'A' OR (SELECT val FROM __erb_dedup_v1) = 'B') THEN ('DANGER')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1) = 'C+' OR (SELECT val FROM __erb_dedup_v1) = 'C-') THEN ('CAUTION')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v1) = 'D' THEN ('SAFE')::text ELSE ('')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_arm_size_ratio
-- Field: TreatmentRankings.ArmSizeRatio
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_arm_size_ratio(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_treatment_rankings_total_cases_a(p_treatment_ranking_id) AS val), __erb_dedup_v2 AS (SELECT calc_treatment_rankings_total_cases_b(p_treatment_ranking_id) AS val) SELECT (CASE WHEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v2)) AS v) __safe_numeric), 0)))::NUMERIC = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v2)) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_treatment_rankings_symmetry_departure
-- Field: TreatmentRankings.SymmetryDeparture
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_treatment_rankings_symmetry_departure(p_treatment_ranking_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_treatment_rankings_arm_size_ratio(p_treatment_ranking_id)) AS v) __safe_numeric), 0) - COALESCE(0.5, 0))))::numeric;
$$ LANGUAGE sql STABLE;

