-- calc_allocation_sweep_is_original
-- Field: AllocationSweep.IsOriginal
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_allocation_sweep_is_original(p_sweep_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT alloc_fraction_a FROM allocation_sweep WHERE sweep_id = p_sweep_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (((SELECT original_alloc_fraction_a::text FROM sweep_study_config WHERE study_id = ((SELECT NULLIF(study_id, '') FROM allocation_sweep WHERE sweep_id = p_sweep_id))::text))) AS v) __safe_numeric), 0))))::NUMERIC < 0.03)::boolean;
$$ LANGUAGE sql STABLE;

