RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (calc_synthetic_phase_phase_signed_pooled_gap(p_phase_id))::NUMERIC > 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN ((SELECT param_stratum_gap1 FROM synthetic_phase WHERE phase_id = p_phase_id))::NUMERIC < 0 THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN ((SELECT param_stratum_gap2 FROM synthetic_phase WHERE phase_id = p_phase_id))::NUMERIC < 0 THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0)))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN ((SELECT param_stratum_gap1 FROM synthetic_phase WHERE phase_id = p_phase_id))::NUMERIC > 0 THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN ((SELECT param_stratum_gap2 FROM synthetic_phase WHERE phase_id = p_phase_id))::NUMERIC > 0 THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_synthetic_phase_phase_reversal_intensity
-- Field: SyntheticPhase.PhaseReversalIntensity
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_synthetic_phase_phase_reversal_intensity(p_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_synthetic_phase_phase_strata_won_by_loser(p_phase_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE(2, 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_synthetic_phase_phase_is_sign_flip
-- Field: SyntheticPhase.PhaseIsSignFlip
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_synthetic_phase_phase_is_sign_flip(p_phase_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_synthetic_phase_phase_signed_pooled_gap(p_phase_id) AS val) SELECT (CASE WHEN (calc_synthetic_phase_phase_corrected_gap(p_phase_id))::NUMERIC > 0 THEN (((SELECT val FROM __erb_dedup_v1))::NUMERIC < 0)::text ELSE (((SELECT val FROM __erb_dedup_v1))::NUMERIC > 0)::text END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_synthetic_phase_phase_allocation_distortion
-- Field: SyntheticPhase.PhaseAllocationDistortion
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_synthetic_phase_phase_allocation_distortion(p_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_synthetic_phase_phase_corrected_gap(p_phase_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_synthetic_phase_phase_signed_pooled_gap(p_phase_id)) AS v) __safe_numeric), 0))))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_synthetic_phase_phase_distortion_type
-- Field: SyntheticPhase.PhaseDistortionType
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_synthetic_phase_phase_distortion_type(p_phase_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_synthetic_phase_phase_is_sign_flip(p_phase_id) AS val), __erb_dedup_v2 AS (SELECT calc_synthetic_phase_phase_reversal_intensity(p_phase_id) AS val), __erb_dedup_v3 AS (SELECT calc_synthetic_phase_phase_allocation_distortion(p_phase_id) AS val), __erb_dedup_v4 AS (SELECT calc_synthetic_phase_phase_signed_pooled_gap(p_phase_id) AS val), __erb_dedup_v5 AS (SELECT calc_synthetic_phase_phase_corrected_gap(p_phase_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1) AND ((SELECT val FROM __erb_dedup_v2))::NUMERIC = 1) THEN ('A')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1) AND ((SELECT val FROM __erb_dedup_v2))::NUMERIC < 1) THEN ('B')::text ELSE (CASE WHEN (NOT ((SELECT val FROM __erb_dedup_v1)) AND ((SELECT val FROM __erb_dedup_v3))::NUMERIC > 0.01 AND ABS((SELECT val FROM __erb_dedup_v4)) > (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v5))) AS v) __safe_numeric), 0) + COALESCE(0.001, 0))) THEN ('C+')::text ELSE (CASE WHEN (NOT ((SELECT val FROM __erb_dedup_v1)) AND ((SELECT val FROM __erb_dedup_v3))::NUMERIC > 0.01 AND ABS((SELECT val FROM __erb_dedup_v4)) < (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (ABS((SELECT val FROM __erb_dedup_v5))) AS v) __safe_numeric), 0) - COALESCE(0.001, 0))) THEN ('C-')::text ELSE ('D')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_phase_diagram_summary_name
-- Field: PhaseDiagramSummary.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_phase_diagram_summary_name(p_phase_diagram_id TEXT)
RETURNS TEXT AS $$
