  SELECT ((SELECT COUNT(*) FROM candidate_study_catalog WHERE calc_candidate_study_catalog_is_imported(candidate_id) = TRUE AND calc_candidate_study_catalog_type_prediction_match(candidate_id) = FALSE))::integer;
$$ LANGUAGE sql STABLE;

