-- calc_corpus_catalog_summary_sign_flip_prediction_match_count
-- Field: CorpusCatalogSummary.SignFlipPredictionMatchCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_corpus_catalog_summary_sign_flip_prediction_match_count(p_catalog_summary_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM candidate_study_catalog WHERE calc_candidate_study_catalog_sign_flip_prediction_match(candidate_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_corpus_catalog_summary_type_prediction_match_rate
-- Field: CorpusCatalogSummary.TypePredictionMatchRate
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_corpus_catalog_summary_type_prediction_match_rate(p_catalog_summary_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_corpus_catalog_summary_imported_count(p_catalog_summary_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN NULL ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_corpus_catalog_summary_type_prediction_match_count(p_catalog_summary_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_corpus_catalog_summary_sign_flip_prediction_match_rate
-- Field: CorpusCatalogSummary.SignFlipPredictionMatchRate
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_corpus_catalog_summary_sign_flip_prediction_match_rate(p_catalog_summary_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_corpus_catalog_summary_sign_flip_prediction_eligible_count(p_catalog_summary_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN NULL ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_corpus_catalog_summary_sign_flip_prediction_match_count(p_catalog_summary_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_corpus_catalog_summary_catalog_witness_note
-- Field: CorpusCatalogSummary.CatalogWitnessNote
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_corpus_catalog_summary_catalog_witness_note(p_catalog_summary_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_corpus_catalog_summary_ready_to_encode_count(p_catalog_summary_id) AS val), __erb_dedup_v2 AS (SELECT calc_corpus_catalog_summary_data_ready_count(p_catalog_summary_id) AS val), __erb_dedup_v3 AS (SELECT calc_corpus_catalog_summary_candidate_count(p_catalog_summary_id) AS val) SELECT (CASE WHEN calc_corpus_catalog_summary_import_session_ready(p_catalog_summary_id) THEN (CONCAT('READY: ', (SELECT val FROM __erb_dedup_v1), ' encode-ready (', (SELECT val FROM __erb_dedup_v2), ' data-ready) of ', (SELECT val FROM __erb_dedup_v3), ' candidates'))::text ELSE (CONCAT('BUILDING: ', (SELECT val FROM __erb_dedup_v3), ' candidates — ', (SELECT val FROM __erb_dedup_v2), ' data-ready, ', (SELECT val FROM __erb_dedup_v1), ' encode-ready'))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_corpus_catalog_summary_catalog_prediction_witness_note
-- Field: CorpusCatalogSummary.CatalogPredictionWitnessNote
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_corpus_catalog_summary_catalog_prediction_witness_note(p_catalog_summary_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT('exact=', calc_corpus_catalog_summary_type_prediction_match_count(p_catalog_summary_id), '/', calc_corpus_catalog_summary_imported_count(p_catalog_summary_id), ' (', ROUND(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_corpus_catalog_summary_type_prediction_match_rate(p_catalog_summary_id)) AS v) __safe_numeric), 0) * COALESCE(100, 0)))::NUMERIC, (1)::INTEGER), '%); flipPred=', calc_corpus_catalog_summary_sign_flip_prediction_match_count(p_catalog_summary_id), '/', calc_corpus_catalog_summary_sign_flip_prediction_eligible_count(p_catalog_summary_id), ' (', ROUND(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_corpus_catalog_summary_sign_flip_prediction_match_rate(p_catalog_summary_id)) AS v) __safe_numeric), 0) * COALESCE(100, 0)))::NUMERIC, (1)::INTEGER), '%)'))::text;
$$ LANGUAGE sql STABLE;

