  SELECT (IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-latent-d", CONCAT("fraction=", (calc_model_summary_latent_type_d_fraction((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-purity", CONCAT("maxPurity=", (calc_model_summary_sign_flip_signal_purity_max((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-small-effect", CONCAT("stable=", (calc_model_summary_avg_pooled_gap_stable_d((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), " latent=", (calc_model_summary_avg_pooled_gap_latent_d((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-econ-zero", CONCAT("flips=", (calc_model_summary_economics_sign_flip_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-domain-dist", CONCAT("epi=", (calc_model_summary_epidemiology_avg_distortion((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), " edu=", (calc_model_summary_education_avg_distortion((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-causal-manifest", CONCAT("confFlip=", (calc_model_summary_confounder_sign_flip_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), " collManifest=", (calc_model_summary_collider_selection_manifest_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-causal-latent", CONCAT("collManifest=", (calc_model_summary_collider_selection_manifest_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), " collLatent=", (calc_model_summary_collider_selection_latent_only_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), " collN=", (calc_model_summary_collider_selection_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-explained-confounder", CONCAT("ExplainedConfounderCount=", (calc_model_summary_explained_confounder_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text))), ", ConfounderSignFlipCount=", (calc_model_summary_confounder_sign_flip_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-unexplained-nonconfounder", CONCAT("ContestedOrMediatorExplainedCount=", (calc_model_summary_contested_or_mediator_explained_count((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE finding_id = p_finding_id) = "H-catalog-exact-match", CONCAT("exactRate=", (calc_model_summary_type_prediction_match_rate((SELECT model_summary_id FROM model_summary WHERE model_summary_id = ('simpsons-paradox-v1')::text)))), IF((SELECT NULLIF(hypothesis_id, '') FROM discovery_findings WHERE 