-- calc_confounder_distortion_timeline_drift_direction
-- Field: ConfounderDistortionTimeline.DriftDirection
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_confounder_distortion_timeline_drift_direction(p_cell_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_confounder_distortion_timeline_identity_earliest_type_d_fr(p_cell_id) AS val), __erb_dedup_v2 AS (SELECT calc_confounder_distortion_timeline_identity_latest_type_d_frac(p_cell_id) AS val) SELECT (CASE WHEN calc_confounder_distortion_timeline_identity_earliest_decade(p_cell_id) = calc_confounder_distortion_timeline_identity_latest_decade(p_cell_id) THEN ('single-decade')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1) IS NULL OR (SELECT val FROM __erb_dedup_v2) IS NULL) THEN ('')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v2) > (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) + COALESCE(0.05, 0)) THEN ('rising')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v2) < (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) - COALESCE(0.05, 0)) THEN ('falling')::text ELSE ('flat')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

